function drawMarkers(){const g=$('mapMarkers');g.replaceChildren();for(const [name,p]of [['A',A],['B',B]]){const q=xy(p),group=el('g',{transform:`translate(${q})`,class:'marker','data-point':name,tabindex:0,role:'button','aria-label':name+' point. Use arrow keys to move'});group.append(el('circle',{r:66,fill:'#ffffff',opacity:.7}),el('circle',{r:46,fill:name==='A'?'#244f40':'#d5ee9b',stroke:'#fff','stroke-width':8}),el('text',{'text-anchor':'middle',y:15,'font-size':40,'font-weight':600,fill:name==='A'?'white':'#244f40'},name));g.append(group);}}
