function applyFacilityLayers(){for(const [id,control] of [['mapStations','layerStations'],['mapRoutes','layerRoutes'],['mapBaseline','layerBaseline'],['mapReachability','layerReach']])$(id).style.display=$(control).checked?'':'none';}
