const errors={OUTSIDE_AREA:'Choose A and B within Central Park and its 1 km buffer.',SNAP_TOO_FAR:'No connected road within 50 m. Move the point closer to a path or park entrance.',NO_EBIKE_OR_WALK_ACCESS:'No available e-bike within the walking limit. Move A or increase the walking limit.',NO_DOCK_OR_WALK_ACCESS:'No available return dock within the walking limit. Move B or increase the walking limit.',NO_ROUTE_WITHIN_STUDY_AREA:'No legal connected route within the study area. Check access and one-way restrictions.',INVALID_COORDINATE:'Enter numeric longitude and latitude.',INVALID_SETTINGS:'Settings are outside the allowed range.',STALE_FEED:'Station data is over five minutes old. Refresh before calculating.'};
