function clearResult(){pendingElapsed=null;clearFacilities();clearTimeout(routeTimer);routeTimer=null;resumeAfterCalculation=false;$('agentAvailability').hidden=true;result=null;current=null;playing=false;playAt=0;sequence=[];humanSequence=[];horseSequence=[];$('agentStatus').textContent='Calculate routes for independent human and horse agents.';$('play').disabled=true;$('scrubber').disabled=true;$('export').disabled=true;$('mapRoutes').replaceChildren();$('mapTraveler').replaceChildren();for(const id of ['kcal','usd'])$(id).textContent='—';$('length').textContent='— km';$('duration').textContent='— min';$('legLength').textContent='— / — km';$('rental').textContent='— / — min';$('stationDetail').textContent='Pickup and return stations appear after calculation.';$('warnings').textContent='';$('comparison').textContent='Compare fares for slope-weighted and fastest candidates.';$('kcalRange').textContent='Depends on body mass and travel time';$('fareDetail').textContent='E-bike billing starts in the first minute';$('play').textContent='▶ Play';drawStations();drawChart();}
function schedule(){const resume=playing||resumeAfterCalculation;clearTimeout(routeTimer);requestID++;clearResult();resumeAfterCalculation=resume;if(built){$('calculate').disabled=false;routeTimer=setTimeout(calculate,300);}}
function calculate(options={}){clearTimeout(routeTimer);routeTimer=null;if(!built)return;const resume=playing||resumeAfterCalculation,elapsed=options.preserveElapsed?playAt:null;let opt;try{opt=settings();}catch(e){resumeAfterCalculation=false;showError(e.message);return;}if(demo)for(const s of stations)s.timestamp=Date.now()/1000;if(imported){const max=Math.max(...stations.map(s=>s.recorded_timestamp??s.timestamp).filter(Number.isFinite));for(const s of stations)s.timestamp=Date.now()/1000-(max-(s.recorded_timestamp??s.timestamp));}clearResult();resumeAfterCalculation=resume;pendingElapsed=elapsed;$('error').hidden=true;$('calculate').disabled=true;$('calculate').firstElementChild.textContent='Finding a route…';const id=++requestID;worker.postMessage({type:'route',id,a:A,b:B,stations,settings:opt});}
function setupWorker(data){worker?.terminate();worker=new Worker('./worker.js',{type:'module'});built=false;worker.onerror=e=>{showError('Cannot load the routing module. Serve the app over HTTP.');$('calculate').disabled=true;};worker.onmessage=({data:r})=>{if(r.type==='built'){built=true;roads=r.roads;drawBase();$('loading').value=3;$('loading').hidden=true;$('calculate').disabled=false;$('calculate').firstElementChild.textContent='Calculate route';if(demo){$('dataStatus').textContent=`Example network · ${r.stats.nodes.toLocaleString()} nodes · not real directions`;}else{const stale=stations.some(s=>Date.now()/1000-s.timestamp>120);$('dataStatus').textContent=`${r.stats.nodes.toLocaleString()} road nodes · ${stations.length} stations\n${stale?'Some station records are over two minutes old.':'Station status connected'} · Battery level unknown`;}if(imported)$('dataStatus').textContent+=' · Saved scenario';if(stateData?.manifest?.gbfs?.status_error)$('dataStatus').textContent+=' · STATUS_UNKNOWN: '+stateData.manifest.gbfs.status_error;$('mapMessage').hidden=true;calculate();}if(r.type==='route'&&r.id===requestID){const resume=resumeAfterCalculation,elapsed=pendingElapsed;resumeAfterCalculation=false;pendingElapsed=null;result=r.result;renderFacilities();renderResult();if(elapsed!==null&&result.diagnostics?.route_cache_hit)playAt=Math.min(elapsed,playbackDuration());playing=resume&&playbackDuration()>0;$('play').textContent=playing?'Ⅱ Pause':'▶ Play';updatePlayback();$('calculate').disabled=false;$('calculate').firstElementChild.textContent='Recalculate route';}if(r.type==='error'&&r.id===requestID){resumeAfterCalculation=false;showError(r.message);$('calculate').disabled=false;$('calculate').firstElementChild.textContent='Recalculate route';}};worker.postMessage({type:'build',raw:data.raw,geometry:data.geometry});}
async function connect(force=false,alternate=false){const token=++epoch;clearInterval(stationTimer);clearResult();built=false;demo=false;imported=false;loading=true;$('calculate').disabled=true;$('retry').disabled=true;$('loading').hidden=false;$('loading').value=0;$('modeBadge').classList.remove('demo');$('modeBadge').innerHTML='<i></i> Connecting live data';$('dataStatus').textContent='1/3 · Loading the official NYC Parks boundary.';$('mapMessage').hidden=false;$('mapMessage').textContent='Loading official map data.';try{const park=await loadBoundary();if(token!==epoch)return;area=makeArea(park.feature.geometry);drawBase();$('loading').value=1;$('dataStatus').textContent='2/3 · Loading roads and stations (initially 1–2 minutes)';const [roadData,stationData]=await Promise.all([loadRoads(area,force,alternate?1:0),loadStations(area).catch(error=>({stations:[],ttl:60,error:error.message}))]);if(token!==epoch)return;$('dataStatus').textContent='Loading real terrain elevations…';raw=await loadTerrain(roadData.raw);if(token!==epoch)return;stations=stationData.stations;stateData={geometry:park.feature.geometry,raw,stations,manifest:{terrain:raw.terrain,boundary:{url:park.source,fetched:park.fetched},osm:{url:roadData.source,timestamp:roadData.timestamp,fetched:roadData.fetched,outdated:roadData.outdated??false},gbfs:{fetched:stationData.fetched,timestamp:stationData.source_timestamp,version:stationData.version,status_error:stationData.status_error??stationData.error??null},projection:'EPSG:32618',policy:POLICY.id,mode:'live'}};$('modeBadge').innerHTML='<i></i> '+(roadData.outdated?'Outdated road cache':'Live data · status at retrieval');$('mapSource').textContent='© OSM contributors · NYC Parks · Citi Bike GBFS';$('dataStatus').textContent='3/3 · Building terrain-weighted graph with access restrictions';setupWorker(stateData);stationTimer=setInterval(()=>refreshStations(true),stationData.ttl*1000);}catch(error){if(token!==epoch)return;$('dataStatus').textContent='Connection failed: '+error.message+' · Retry with another server or select the example.';$('modeBadge').innerHTML='<i></i> Live data disconnected';$('loading').hidden=true;$('mapMessage').textContent='Live data unavailable. Retry or explore the synthetic example.';$('mapSource').textContent='Before data connection · schematic location';}finally{if(token===epoch){loading=false;$('retry').disabled=false;}}}
async function refreshStations(recalculate=true){if(demo||imported){if(recalculate)calculate({preserveElapsed:true});return;}if(!built)return;const token=epoch,request=++stationRefreshID;try{const data=await loadStations(area);if(token!==epoch||request!==stationRefreshID)return;stations=data.stations;stateData.stations=stations;stateData.manifest.gbfs={fetched:data.fetched,timestamp:data.source_timestamp,version:data.version,status_error:data.status_error??null};drawStations();$('dataStatus').textContent=`Stations ${stations.length} · ${new Date(data.fetched).toLocaleTimeString('en-US',{timeZone:'America/New_York'})} New York time · battery unknown${data.status_error?' · STATUS_UNKNOWN: '+data.status_error:''}`;if(recalculate)calculate({preserveElapsed:true});}catch(error){if(token!==epoch||request!==stationRefreshID)return;$('dataStatus').textContent='Station refresh failed · retaining original timestamps · '+error.message;stations=stations.map(s=>({...s,status_present:false,status_error:error.message}));stateData.stations=stations;stateData.manifest.gbfs={...stateData.manifest.gbfs,status_error:error.message};if(recalculate)calculate({preserveElapsed:true});}}
function useExample(){epoch++;clearInterval(stationTimer);const d=exampleData();demo=true;imported=false;loading=false;$('retry').disabled=false;raw=d.raw;stations=d.stations;A=d.a;B=d.b;area=makeArea(d.geometry);stateData={...d,manifest:{mode:'synthetic-example',projection:'EPSG:32618',policy:POLICY.id,created:new Date().toISOString()}};$('modeBadge').classList.add('demo');$('modeBadge').innerHTML='<i></i> Synthetic example · not real directions';$('mapSource').textContent='Synthetic network · not real roads or stations';$('placeA').value=String(places.length-1);$('placeB').value=String(places.length-1);updateCoords();clearResult();setupWorker(stateData);}
function routeMessage(code){return ({NO_SHARED_HUMAN_ROUTE:'The shared human route is unavailable. Calculate a connected human route first.',SNAP_TOO_FAR:'No permitted route within 50 m of A or B. Move A and B closer to the connected human route.',INVALID_HORSE_FARE:'Enter a valid carriage tariff and time unit.',INVALID_HORSE_SETTINGS:'Horse settings are outside the permitted range.'})[code]??errors[code]??code;}
function focusedAgent(){return $('agentFocus').checked?'horse':'human';}
function playbackDuration(){return Math.max(result?.shortest?.totalSeconds??0,result?.horse?.totalSeconds??0);}
function renderResult(){
 const selected=focusedAgent(),name=selected==='horse'?'Horse':'Human';current=selected==='horse'?result.horse:result.shortest;
 humanSequence=result.shortest?makeSequence(result.shortest):[];horseSequence=result.horse?makeSequence(result.horse):[];
 if(selected==='horse'&&!current?.fare&&metric==='usd'){metric='kcal';$('chartUnit').textContent='energy';for(const b of document.querySelectorAll('[data-metric]'))b.classList.toggle('selected',b.dataset.metric==='kcal');}
 $('agentAvailability').hidden=!!current;
 $('agentAvailability').textContent=current?'':`${name} route unavailable. ${routeMessage(selected==='horse'?result.horseError:result.humanError)} ${selected==='horse'?'Move A and B onto connected human paths, then calculate again.':'Check the human route endpoints and bike station availability.'}`;
 if(!current){
  sequence=[];$('error').hidden=true;$('costAgent').textContent=name+' · route unavailable';$('energyLegend').textContent=name+' cumulative energy · left axis';
  for(const id of ['kcal','usd','length','duration','legLength','rental'])$(id).textContent='—';
  $('kcalRange').textContent='No energy estimate without a connected route.';$('fareDetail').textContent='No fare estimate available.';$('stationDetail').textContent=$('agentAvailability').textContent;
  $('warnings').textContent=$('agentAvailability').textContent;$('comparison').textContent='No route comparison available.';$('compare').disabled=true;document.querySelector('[data-metric=usd]').disabled=true;
  $('export').disabled=true;$('play').disabled=playbackDuration()===0;$('scrubber').disabled=playbackDuration()===0;
  drawRoutes();drawStations();drawChart();updatePlayback();return;
 }
 const j=current,isHorse=j.agent==='horse';sequence=isHorse?horseSequence:humanSequence;
 if(isHorse&&!j.fare&&metric==='usd'){metric='kcal';$('chartUnit').textContent='energy';for(const b of document.querySelectorAll('[data-metric]'))b.classList.toggle('selected',b.dataset.metric==='kcal');}
 document.querySelector('[data-metric=usd]').disabled=!j.fare;$('costAgent').textContent=isHorse?'Horse · metabolic scenario':'Human · e-bike journey';$('energyLegend').textContent=isHorse?'Horse cumulative energy / cost · left axis':'Human cumulative energy / fare · left axis';
 $('error').hidden=true;$('kcal').textContent=Math.round(j.kcal);$('usd').textContent=j.fare?(j.fare.total/100).toFixed(2):'N/A';
 $('kcalRange').textContent=isHorse?`Scenario: resting ${Math.round(j.energy.resting)}, movement ${Math.round(j.energy.locomotion)}, climbing ${Math.round(j.energy.climbing)} kcal · not calibrated`:`Estimated range ${Math.round(j.low)}–${Math.round(j.high)} kcal · active ${Math.round(j.active)} kcal`;
 $('fareDetail').textContent=isHorse?(j.fare?`${money(j.fare.base_price)} / first ${j.fare.base_minutes} min + ${j.fare.extra_units} × ${money(j.fare.extra_price??0)} per ${j.fare.extra_minutes} extra min · per carriage`:'Enter the carriage base and extra-time prices in Horse model settings to estimate cost.'):j.fare?`Unlock ${money(j.fare.unlock)} + riding ${money(j.fare.ride)}${j.fare.pass?' + pass '+money(j.fare.pass):''}`:'Citi Bike fares do not apply to the horse.';
 $('movementLabel').textContent=isHorse?'Movement':'Walk / ride';$('length').textContent=km(j.length)+' km';$('duration').textContent=mins(j.totalSeconds)+' min';$('legLength').textContent=isHorse?'Shared human route':km(j.walkLength)+' / '+km(j.rideLength)+' km';$('rental').textContent=isHorse?(j.fare?`${mins(j.totalSeconds)} / ${j.fare.billed_minutes} min`:'N/A'):j.fare?mins(j.rental)+' / '+j.fare.minutes+' min':'N/A';
 $('stationDetail').textContent=isHorse?`Horse ${j.settings.mass} kg · base speed ${j.settings.speed} km/h · shared human route`:j.start?`S · ${j.start.name} (e-bikes ${j.start.ebikes??'?'})\nT · ${j.end.name} (docks ${j.end.docks??'?'})`:'A and B coincide. No rental or travel required.';
 $('stationDetail').style.whiteSpace='pre-line';const notes=[];
 if(demo)notes.push('Synthetic example, not real directions.');if(imported)notes.push('Saved snapshot scenario; not current conditions.');
 if(isHorse&&j.fare)notes.push(`Price source: ${j.fare.source}. User-entered carriage estimate, not a verified market price. Taxes and tips are not added.`);
 if(isHorse)notes.push('Editable oxygen-cost and uphill-work scenario, not measured equine metabolism or feed energy. Human route geometry is shared for simulation; horse access rules are not used to select this route.');else notes.push('Excludes tax/discounts · dock/battery availability not guaranteed.');
 if(j.fare?.warnings.length)notes.push('Long-ride billing rules unverified.');
 if(j.legs?.some(l=>l.snapStart?.distance>2||l.snapEnd?.distance>2))notes.push('Endpoints are projected onto permitted paths within 50 m; access to those projections is unverified.');
 notes.push(j.elevation?.known?`Terrain ascent: ${j.elevation.ascent.toFixed(1)} m · Maximum grade: ${(j.elevation.maxGrade*100).toFixed(1)}% · Weighted distance: ${(j.weightedDistance/1000).toFixed(2)} km`:'Terrain elevations unavailable in this example or legacy snapshot; slope is not evaluated.');
 if(result.horseError)notes.push('Horse: '+routeMessage(result.horseError));if(result.humanError)notes.push('Human: '+routeMessage(result.humanError));$('warnings').textContent=notes.join(' ');
 $('compare').disabled=isHorse;$('comparison').textContent=isHorse?'Same geometry as the human route; horse speed, slope cost and metabolic calculations remain independent. Horse cost uses the entered per-carriage base and additional-time tariff, if provided.':result.cheapest?`${result.candidates} station pairs · comparison fare ${money(result.cheapest.fare.total)} · ${km(result.cheapest.length)} km`:'No fare comparison available.';
 drawRoutes();drawStations();playAt=0;playing=false;$('play').textContent='▶ Play';$('play').disabled=playbackDuration()===0;$('scrubber').disabled=playbackDuration()===0;$('export').disabled=false;drawChart();updatePlayback();$('provenance').textContent=stateData?JSON.stringify(stateData.manifest,null,2):'';
}
// Both series share elapsed time, including flat elevation during stops.
function drawElevation(chart,total,margin,width,height){
 const status=$('terrainStatus');
 const samples=sequence.flatMap(s=>[[s.start,s.h0],[s.end,s.h1]]);
 if(!current.elevation?.known||!samples.length||samples.some(p=>!Number.isFinite(p[1]))){status.textContent='Elevation unavailable in this dataset.';return;}
 if(samples.at(-1)[0]<total)samples.push([total,samples.at(-1)[1]]);
 const low=Math.min(...samples.map(p=>p[1])),high=Math.max(...samples.map(p=>p[1]));
 const padding=Math.max(1,(high-low)*.1),min=low-padding,max=high+padding;
 status.textContent=`Terrain ${low.toFixed(1)}–${high.toFixed(1)} m · DEM estimates`;
 for(let i=0;i<=3;i++)chart.append(el('text',{x:margin+width+8,y:135-i*height/3+3,fill:'#a77143','font-size':10},(min+(max-min)*i/3).toFixed(1)));
 chart.append(el('text',{x:margin+width,y:11,'text-anchor':'end',fill:'#a77143','font-size':10},'Elevation (m)'));
 chart.append(el('path',{id:'elevationOverlay',d:samples.map(([t,h],i)=>(i?'L':'M')+(margin+width*t/total).toFixed(3)+','+(135-height*(h-min)/(max-min)).toFixed(3)).join(' '),fill:'none',stroke:'#a77143','stroke-width':2.5,'stroke-dasharray':'7 4','stroke-linejoin':'round'}));
}
function drawRoutes(){
 const g=$('mapRoutes');g.replaceChildren();
 const draw=(j,color,dash,kind)=>{if(!j)return;for(const leg of j.legs){if(!leg.points?.length)continue;const d=path(leg.points);if(kind!=='horse')g.append(el('path',{d,class:'route-line',stroke:'#fff','stroke-width':32}));g.append(el('path',{d,class:'route-line','data-route-agent':kind,stroke:color,'stroke-width':kind==='horse'?9:18,'stroke-dasharray':kind==='human'&&leg.mode==='walk'?'12 14':dash}));}};
 if($('compare').checked&&current?.agent!=='horse')draw(result?.cheapest,'#999','10 20','comparison');
 draw(result?.shortest,'#1263ad',null,'human');draw(result?.horse,'#8a3f86','28 18','horse');
}
function makeSequence(j){const list=[];let time=0,kcal=0;const add=(duration,met,p0,p1,rental=false,customKcal=null)=>{if(duration<1e-7)return;const k=customKcal??energy(duration/60,j.settings?.mass??70,met).gross;list.push({start:time,end:time+duration,k0:kcal,k1:kcal+k,p0,p1,rental});time+=duration;kcal+=k;};for(let n=0;n<j.legs.length;n++){const l=j.legs[n];if(l.mode==='ride')add(30,1.3,l.points[0],l.points[0],true);for(let i=0;i<l.path.length;i++){const edge=l.path[i],p0=l.points[i],p1=l.points[i+1];const speed=l.mode==='walk'?(j.settings.walkSpeed??4.8):l.mode==='horse'?j.settings.speed:Math.min(edge.speed,j.settings.speed,24.14);add(slopeSeconds(edge,speed),l.mode==='walk'?(j.settings.walkMet??3.5):j.settings.met,p0,p1,l.mode==='ride',l.mode==='horse'?horseEdgeEnergy(edge,j.settings).gross:null);if(l.mode==='ride'&&edge.delay&&i<l.path.length-1)add(edge.delay,1.3,p1,p1,true);}if(l.mode==='ride'){const allotted=l.seconds+60+j.settings.pause*60;const actual=list.filter(s=>s.rental).reduce((v,s)=>v+s.end-s.start,0);add(Math.max(0,allotted-actual),1.3,l.points.at(-1),l.points.at(-1),true);}}
 const nodes=new Map((raw?.elements??[]).filter(n=>n.type==='node').map(n=>[n.id,n]));
 const heights=new Map(),key=p=>p.map(v=>v.toFixed(4)).join(',');
 if(j.elevation?.known)for(const leg of j.legs)for(let i=0;i<leg.path.length;i++){
  const edge=leg.path[i],node=nodes.get(edge.u);if(!node)continue;
  const origin=project([node.lon,node.lat]),offset=edge.fromPoint?distance(origin,edge.fromPoint):0;
  const h=Number(node.tags?.ele)+edge.grade*offset;
  heights.set(key(leg.points[i]),h);heights.set(key(leg.points[i+1]),h+edge.grade*edge.length);
 }
 for(const seg of list){seg.h0=heights.get(key(seg.p0));seg.h1=heights.get(key(seg.p1));}
 return list;}
function valueAt(t,seq=sequence,route=current){const seg=seq.find(s=>t<s.end)??seq.at(-1);if(!seg)return {kcal:0,cents:0,p:A};const f=Math.max(0,Math.min(1,(t-seg.start)/(seg.end-seg.start))),rentalStart=seq.find(s=>s.rental)?.start??Infinity,rentalEnd=seq.filter(s=>s.rental).at(-1)?.end??Infinity,rental=Math.max(0,Math.min(t,rentalEnd)-rentalStart);const cents=route.agent==='horse'?(route.fare?horseFare(Math.max(0,Math.min(t,route.totalSeconds)),route.settings)?.total??0:0):t>=rentalStart?(fare(Math.max(.001,rental),route.settings.profile,route.settings.newPass).total):0;return {kcal:seg.k0+(seg.k1-seg.k0)*f,cents,p:[seg.p0[0]+(seg.p1[0]-seg.p0[0])*f,seg.p0[1]+(seg.p1[1]-seg.p0[1])*f]};}
function drawChart(){const chart=$('chart');chart.replaceChildren();$('terrainStatus').textContent='Elevation appears when terrain data is available.';if(!current){$('terrainStatus').textContent=result?'No elevation profile for the selected agent.':'Elevation appears when terrain data is available.';chart.append(el('text',{x:500,y:85,'text-anchor':'middle',fill:'#8a948c','font-size':14},result?`${focusedAgent()==='horse'?'Horse':'Human'} route unavailable — see the guidance above.`:'Calculate a route to display cumulative cost over time.'));return;}const max=metric==='kcal'?current.kcal:current.fare.total/100,margin=55,width=890,height=110,total=playbackDuration()||1;for(let i=0;i<=3;i++){const y=135-i*height/3;chart.append(el('line',{x1:margin,x2:margin+width,y1:y,y2:y,stroke:'#e6eadf','stroke-dasharray':'3 4'}),el('text',{x:0,y:y+3,fill:'#9aa58f','font-size':10},(max*i/3).toFixed(metric==='usd'?2:0)));}let pts=[];const times=new Set([0,total,...sequence.flatMap(s=>[s.start,s.end])]);if(metric==='usd'&&current.agent==='horse'){times.add(Math.min(total,.0001));for(let t=current.fare.base_minutes*60;t<current.totalSeconds;t+=current.fare.extra_minutes*60){times.add(t);times.add(Math.min(total,t+.0001));}}if(metric==='usd'){const rstart=sequence.find(s=>s.rental)?.start;if(rstart!==undefined){times.add(Math.max(0,rstart-.0001));times.add(rstart);for(let i=0;i<=current.fare.minutes;i++){const t=rstart+i*60;if(t<=total){times.add(t);times.add(Math.min(total,t+.0001));}}}}else for(let i=0;i<=100;i++)times.add(total*i/100);for(const t of [...times].sort((a,b)=>a-b)){const val=valueAt(t),v=metric==='kcal'?val.kcal:val.cents/100;pts.push([margin+t/total*width,135-(max?v/max:0)*height]);}const d=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' '),color=metric==='kcal'?'#7e9e5f':'#b98d59';chart.append(el('path',{d:d+` L${margin+width},135 L${margin},135 Z`,fill:metric==='kcal'?'#edf3e3':'#f5eee3'}),el('path',{id:'cumulativeOverlay',d,stroke:color,'stroke-width':2,fill:'none'}),el('line',{id:'playhead',x1:margin,x2:margin,y1:10,y2:137,stroke:'#365d44','stroke-width':1}));drawElevation(chart,total,margin,width,height);chart.append(el('text',{x:margin,y:11,fill:color,'font-size':10},metric==='kcal'?'Energy (kcal)':'Fare (USD)'));chart.append($('playhead'));for(let i=0;i<=4;i++)chart.append(el('text',{x:margin+i*width/4,y:157,'text-anchor':'middle',fill:'#9aa58f','font-size':10},mins(total*i/4)+'min'));}
// Screen-sized badges share a geographic anchor without hiding one another.
function drawAgents(){
 const rect=$('map').getBoundingClientRect();
 const scale=Math.max(view[2]/Math.max(1,rect.width),view[3]/Math.max(1,rect.height));
 const layer=$('mapTraveler');layer.replaceChildren();
 for(const [kind,offset,color] of [['human',-28,'#1263ad'],['horse',28,'#8a3f86']]){
  const route=kind==='human'?result?.shortest:result?.horse;if(!route)continue;const point=valueAt(playAt,kind==='human'?humanSequence:horseSequence,route).p,q=xy(point);
  const label=kind==='human'?'Human':'Horse';
  const group=el('g',{'data-agent':kind,'data-x':point[0],'data-y':point[1],transform:`translate(${q}) scale(${scale})`,class:'agent-marker'+(playing&&playAt<route.totalSeconds?' is-moving':''),role:'img','aria-label':label+' agent'});
  group.append(el('title',{},label+' · shared route, independent speed'),el('path',{d:`M0,0 L${offset},-26`,stroke:color,'stroke-width':1.2,opacity:.65}),el('circle',{r:3,fill:color}));
  const badge=el('g',{transform:`translate(${offset},-30)`});
  badge.append(kind==='human'?el('circle',{r:19,fill:'#edf5ff',stroke:color,'stroke-width':2.5}):el('rect',{x:-19,y:-19,width:38,height:38,rx:5,fill:'#f9eff8',stroke:color,'stroke-width':2.5}));badge.append(el('text',{x:0,y:32,'text-anchor':'middle','font-size':10,'font-weight':700,fill:color,stroke:'#fff','stroke-width':3,'paint-order':'stroke'},label.toUpperCase()));
  if(kind==='human'){
   badge.append(el('circle',{cx:0,cy:-9,r:3,fill:color}),el('path',{d:'M0 -4 L-2 3 M0 -4 L5 1 L9 1 M0 -4 L-6 0 L-9 -2',fill:'none',stroke:color,'stroke-width':2.6,'stroke-linecap':'round','stroke-linejoin':'round'}),el('path',{d:'M-2 3 L-6 11 M-2 3 L4 6 L6 11',fill:'none',stroke:color,'stroke-width':2.6,'stroke-linecap':'round',class:'agent-legs'}));
  }else{
   badge.append(el('path',{d:'M-10 -3 Q-3 -6 4 -3 L7 -10 L7 -14 L10 -11 L13 -9 L14 -4 L10 -3 L8 -5 L6 4 L-7 4 L-10 0 L-12 5 L-14 3 Z',fill:color}),el('path',{d:'M-7 2 L-8 11 M-2 3 L0 11 M5 2 L5 11 M8 0 L10 9',fill:'none',stroke:color,'stroke-width':2.3,'stroke-linecap':'round',class:'agent-legs'}),el('circle',{cx:11,cy:-8,r:.8,fill:'#fff'}));
  }
  group.append(badge);layer.append(group);
 }
}
function updatePlayback(){if(!result)return;const val=current?valueAt(playAt):null;const duration=playbackDuration();$('clock').textContent=clock(playAt)+' / '+clock(duration);$('agentStatus').textContent=[['Human',result.shortest,result.humanError],['Horse',result.horse,result.horseError]].map(([name,r,error])=>r?`${name}: ${clock(Math.min(playAt,r.totalSeconds))} / ${clock(r.totalSeconds)} · ${playAt>=r.totalSeconds?'Arrived':playing?'Moving':'Paused'} · ${Math.round(valueAt(playAt,name==='Horse'?horseSequence:humanSequence,r).kcal)} kcal`:name+': '+routeMessage(error)).join(' | ');$('scrubber').value=duration?playAt/duration*1000:0;$('currentCost').textContent=val?'Cumulative '+(metric==='kcal'?Math.round(val.kcal)+' kcal':money(val.cents)+' USD'):`${focusedAgent()==='horse'?'Horse':'Human'} route unavailable`;const x=55+(duration?playAt/duration:0)*890;const ph=$('playhead');if(ph){ph.setAttribute('x1',x);ph.setAttribute('x2',x);}drawAgents();}
let lastFrame=0;function frame(now){if(playing&&result){playAt=Math.min(playbackDuration(),playAt+Math.min((now-lastFrame)/1000,.2)*Number($('playSpeed').value));updatePlayback();if(playAt>=playbackDuration()){playing=false;$('play').textContent='▶ Replay';updatePlayback();}}lastFrame=now;requestAnimationFrame(frame);}requestAnimationFrame(frame);
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=async()=>{if(!result||!current)return;const manifest={...stateData.manifest,exported:new Date().toISOString(),osm_sha256:await hashJSON(raw),boundary_sha256:await hashJSON(stateData.geometry)};const rows=['elapsed_seconds,gross_kcal,pre_tax_usd'];for(let t=0;t<playbackDuration();t+=10){const v=valueAt(t);rows.push(`${t},${v.kcal.toFixed(3)},${current.fare?(v.cents/100).toFixed(2):''}`);}const v=valueAt(playbackDuration());rows.push(`${playbackDuration()},${v.kcal.toFixed(3)},${current.fare?(v.cents/100).toFixed(2):''}`);const blob=zipFiles({'result.json':{selected_agent:focusedAgent(),schema:'cp-distance-1',a:unproject(A),b:unproject(B),settings:settings(),result,manifest},'route.geojson':{type:'FeatureCollection',features:current.legs.map(l=>l.geojson)},'cumulative.csv':rows.join('\n'),'proximity.csv':facilityCsv(),'comparison.json':{baseline:result.proximity?.baseline,trip:result.trip,candidateSelection:result.candidateSelection,data_quality:result.proximity?.data_quality},'snapshot.json':{schema:'cp-snapshot-1',...stateData,manifest,a:unproject(A),b:unproject(B),settings:settings()}});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='central-park-journey.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>40*1024*1024)throw new Error('File must be no larger than 40 MB.');const d=JSON.parse(await file.text());if(d.schema!=='cp-snapshot-1'||!d.geometry||!Array.isArray(d.raw?.elements)||!Array.isArray(d.stations))throw new Error('Invalid snapshot file.');if(d.manifest?.osm_sha256&&d.manifest.osm_sha256!==await hashJSON(d.raw))throw new Error('Road data hash mismatch.');if(d.manifest?.boundary_sha256&&d.manifest.boundary_sha256!==await hashJSON(d.geometry))throw new Error('Boundary data hash mismatch.');epoch++;clearInterval(stationTimer);area=makeArea(d.geometry);raw=d.raw;stations=d.stations;demo=false;imported=true;stateData=d; // Replay uses a fixed availability snapshot; original timestamps stay in manifest.
 const snapshotNow=Math.max(...stations.map(s=>s.timestamp).filter(Number.isFinite));for(const s of stations){s.recorded_timestamp=s.recorded_timestamp??s.timestamp;s.timestamp=Date.now()/1000-(snapshotNow-s.timestamp);}if(d.a)A=project(d.a);if(d.b)B=project(d.b);if(d.settings){if(!('routingObjective' in d.settings))$('routingObjective').value='weighted';for(const id of ['mass','speed','met','walkLimit','pause','profile','walkMet','walkSpeed','walkThresholdMin','maxStationCandidates','routingObjective','maxWalkAccessMin'])if(d.settings[id]!==undefined)$(id).value=d.settings[id];$('newPass').checked=!!d.settings.newPass;if(d.settings.horse)for(const [key,id] of Object.entries({mass:'horseMass',speed:'horseSpeed',restO2:'horseRestO2',costO2:'horseCostO2',efficiency:'horseEfficiency',ridePrice:'horseRidePrice',rideMinutes:'horseRideMinutes',extraPrice:'horseExtraPrice',extraMinutes:'horseExtraMinutes',fareSource:'horseFareSource'}))if(d.settings.horse[key]!==undefined)$(id).value=d.settings.horse[key];}updateCoords();updateRate();$('modeBadge').classList.add('demo');$('modeBadge').innerHTML='<i></i> Saved scenario · not current conditions';$('mapSource').textContent='Imported snapshot · '+(d.manifest?.exported??'unknown time');clearResult();setupWorker(d);}catch(error){showError('Import failed: '+error.message);}e.target.value='';};
function updateRate(){const p=POLICY.profiles[$('profile').value];$('rateNote').textContent=`Unlock ${money(p.unlock)} + ${money(p.rate)} / min`;$('newPass').disabled=$('profile').value!=='day';}
for(const name of ['A','B']){const sel=$('place'+name);places.forEach(([label],i)=>{const o=document.createElement('option');o.value=i;o.textContent=label;sel.append(o);});sel.value=name==='A'?0:7;sel.onchange=()=>{const p=places[Number(sel.value)][1];if(p)choosePoint(name,project(p));sel.value=String(places.findIndex(x=>x[1]&&distance(project(x[1]),name==='A'?A:B)<1));};$('coord'+name).onchange=()=>{const ll=$('coord'+name).value.split(',').map(s=>Number(s.trim()));if(ll.length!==2||!ll.every(Number.isFinite)||Math.abs(ll[0])>180||Math.abs(ll[1])>90){showError('INVALID_COORDINATE');return;}choosePoint(name,project(ll));};$('pick'+name).onclick=()=>{selected=name;for(const n of ['A','B']){$('pick'+n).classList.toggle('active',name===n);$('pick'+n).setAttribute('aria-pressed',String(name===n));}};}
$('facilityRole').onchange=()=>{renderFacilities();drawStations();};
$('facilityRows').onclick=e=>{const button=e.target.closest('[data-inspect-station]');if(button){inspectedStation=button.dataset.inspectStation;renderFacilities();drawStations();}};
$('mapStations').onkeydown=e=>{if(['Enter',' '].includes(e.key)){const marker=e.target.closest('[data-station]');if(marker){e.preventDefault();inspectedStation=marker.dataset.station;renderFacilities();drawStations();}}};
for(const id of ['layerStations','layerRoutes','layerBaseline','layerReach'])$(id).onchange=applyFacilityLayers;
$('agentFocus').onchange=()=>{if(result){const elapsed=playAt,resume=playing;renderResult();playAt=Math.min(elapsed,playbackDuration());playing=resume;$('play').textContent=playing?'Ⅱ Pause':'▶ Play';updatePlayback();}};
$('swap').onclick=()=>{[A,B]=[B,A];[$('placeA').value,$('placeB').value]=[$('placeB').value,$('placeA').value];updateCoords();drawMarkers();schedule();};$('profile').onchange=()=>{updateRate();schedule();};for(const id of ['mass','speed','met','walkLimit','pause','walkMet','walkSpeed','walkThresholdMin','maxStationCandidates','routingObjective','maxWalkAccessMin','newPass','horseMass','horseSpeed','horseRestO2','horseCostO2','horseEfficiency','horseRidePrice','horseRideMinutes','horseExtraPrice','horseExtraMinutes','horseFareSource'])$(id).onchange=schedule;$('calculate').onclick=calculate;$('retry').onclick=()=>connect(false,true);$('example').onclick=useExample;$('refresh').onclick=()=>built?refreshStations():connect();$('compare').onchange=drawRoutes;
for(const btn of document.querySelectorAll('[data-metric]'))btn.onclick=()=>{metric=btn.dataset.metric;document.querySelectorAll('[data-metric]').forEach(b=>b.classList.toggle('selected',b===btn));$('chartUnit').textContent=metric==='kcal'?'energy':'fare';drawRoutes();drawChart();updatePlayback();};
$('play').onclick=()=>{if(!result||!playbackDuration())return;if(playAt>=playbackDuration())playAt=0;playing=!playing;$('play').textContent=playing?'Ⅱ Pause':'▶ Play';updatePlayback();};$('reset').onclick=()=>{resumeAfterCalculation=false;playing=false;playAt=0;$('play').textContent='▶ Play';updatePlayback();};$('scrubber').oninput=()=>{playing=false;$('play').textContent='▶ Play';playAt=Number($('scrubber').value)/1000*playbackDuration();updatePlayback();};$('aboutButton').onclick=()=>$('about').showModal();$('closeAbout').onclick=()=>$('about').close();$('about').onclick=e=>{if(e.target===$('about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
const screenPoint=e=>{const p=$('map').createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform($('map').getScreenCTM().inverse());return [q.x,q.y];};let drag=null;
$('map').onpointerdown=e=>{if(e.button!==0)return;const marker=e.target.closest('[data-point]');drag={name:marker?.getAttribute('data-point'),start:screenPoint(e),client:[e.clientX,e.clientY],station:e.target.closest('[data-station]')?.getAttribute('data-station'),view:[...view],moved:false};$('map').setPointerCapture(e.pointerId);};
$('map').onpointermove=e=>{if(!drag)return;drag.moved ||=Math.hypot(e.clientX-drag.client[0],e.clientY-drag.client[1])>4;if(drag.name){const p=world(screenPoint(e));if(area.contains(p)){if(drag.name==='A')A=p;else B=p;drawMarkers();updateCoords();}}else if(drag.moved){const dx=(e.clientX-drag.client[0])/$('map').getBoundingClientRect().width*drag.view[2],dy=(e.clientY-drag.client[1])/$('map').getBoundingClientRect().height*drag.view[3];view=[drag.view[0]-dx,drag.view[1]-dy,drag.view[2],drag.view[3]];setView();}};
$('map').onpointerup=e=>{if(!drag)return;const d=drag;drag=null;if(d.name){$('place'+d.name).value=String(places.length-1);schedule();}else if(!d.moved){const station=d.station;if(station){const s=stations.find(s=>s.id===station);inspectedStation=s.id;renderFacilities();drawStations();}else choosePoint(selected,world(screenPoint(e)));}};$('map').onpointercancel=()=>drag=null;
$('map').onkeydown=e=>{const m=e.target.closest('[data-point]');if(!m)return;const dirs={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,10],ArrowDown:[0,-10]};if(dirs[e.key]){e.preventDefault();const name=m.getAttribute('data-point'),p=name==='A'?A:B;choosePoint(name,[p[0]+dirs[e.key][0],p[1]+dirs[e.key][1]]);document.querySelector('[data-point="'+name+'"]').focus();}};
function zoom(factor,center){const c=center??[view[0]+view[2]/2,view[1]+view[3]/2],w=Math.max(baseView[2]/10,Math.min(baseView[2]*2,view[2]*factor)),h=w*baseView[3]/baseView[2],fx=(c[0]-view[0])/view[2],fy=(c[1]-view[1])/view[3];view=[c[0]-w*fx,c[1]-h*fy,w,h];setView();}$('map').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89,screenPoint(e));},{passive:false});$('zoomIn').onclick=()=>zoom(.8);$('zoomOut').onclick=()=>zoom(1.25);$('fit').onclick=fit;
window.addEventListener('resize',()=>{if(result)drawAgents();});
window.addEventListener('beforeunload',()=>{worker?.terminate();clearInterval(stationTimer);});updateCoords();updateRate();drawBase();connect();
